// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/access_token", wrapper.ExchangeInstagramLongLivedToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/oauth/access_token", wrapper.ExchangeInstagramAuthorizationCode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/oauth/authorize", wrapper.AuthorizeInstagramBusinessLogin)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/refresh_access_token", wrapper.RefreshInstagramLongLivedToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v24.0/debug_token", wrapper.DebugFacebookAccessToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v24.0/dialog/oauth", wrapper.AuthorizeFacebookLogin)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v24.0/me/permissions", wrapper.RevokeFacebookAuthorizationSelf)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v24.0/me/permissions", wrapper.GetFacebookPermissionsSelf)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v24.0/oauth/access_token", wrapper.ExchangeFacebookAccessToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v24.0/oauth/client_code", wrapper.CreateFacebookClientCode)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v24.0/{objectID}/permissions", wrapper.RevokeFacebookAuthorizationById)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v24.0/{objectID}/permissions", wrapper.GetFacebookPermissionsById)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v24.0/{objectID}/permissions/{permission_name}", wrapper.RevokeFacebookPermission)

	return m
}
